import{_t as e,it as t,n,rt as r}from"./chunks/framework.BJB2RXm-.js";var i=JSON.parse(`{"title":"Maintenance","description":"","frontmatter":{},"headers":[],"relativePath":"maintenance.md","filePath":"maintenance.md"}`),a={name:`maintenance.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to “Maintenance”">​</a></h1><p>Keep documentation and dependencies current as the monorepo changes.</p><h2 id="documentation-maintenance" tabindex="-1">Documentation maintenance <a class="header-anchor" href="#documentation-maintenance" aria-label="Permalink to “Documentation maintenance”">​</a></h2><p>Update documentation in the same pull request as the related change.</p><p>Documentation should be reviewed when you:</p><ul><li>Add, remove, or change Nx targets or defaults.</li><li>Change CI/CD workflows.</li><li>Add or rename a plugin or theme.</li><li>Change release, versioning, Composer, or deployment behaviour.</li></ul><p>For project-specific changes, update documentation under:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/&lt;plugin-slug&gt;/docs/</span></span>
<span class="line"><span>themes/&lt;theme-slug&gt;/docs/</span></span></code></pre></div><p>For monorepo-wide documentation, update the appropriate page under <code>docs/</code>.</p><h3 id="editing-documentation" tabindex="-1">Editing documentation <a class="header-anchor" href="#editing-documentation" aria-label="Permalink to “Editing documentation”">​</a></h3><ul><li>Edit monorepo documentation under <code>docs/</code>.</li><li>Edit package documentation under the package&#39;s <code>docs/</code> directory.</li><li>Use <code>pnpm docs:dev</code> to preview documentation locally.</li><li>Update <code>docs/.vitepress/config.mts</code> when a new top-level page requires navigation.</li><li>Do not edit <code>docs/content/</code>. It is generated by <code>tools/sync-docs.mjs</code>.</li></ul><h2 id="dependency-maintenance" tabindex="-1">Dependency maintenance <a class="header-anchor" href="#dependency-maintenance" aria-label="Permalink to “Dependency maintenance”">​</a></h2><p>Dependabot manages npm and Composer dependency update pull requests through <code>.github/dependabot.yml</code>.</p><p>Current schedules are:</p><ul><li>npm: daily</li><li>Composer: weekly on Monday</li></ul><p>Dependabot allows up to three open pull requests per ecosystem. Reviews are assigned to <code>@bcgov/digital-engagement-solutions-custom-web</code>.</p><h3 id="wordpress-dependencies" tabindex="-1">WordPress dependencies <a class="header-anchor" href="#wordpress-dependencies" aria-label="Permalink to “WordPress dependencies”">​</a></h3><p>Production WordPress is currently <code>6.7.4</code>.</p><p>Shared <code>@wordpress/*</code> versions are managed through the <code>pnpm-workspace.yaml</code> catalog using <code>wp-6.7</code> releases. Updates to these packages must remain compatible with the production WordPress version.</p><p>Do not merge a dependency update when:</p><ul><li>CI fails because of the update.</li><li>The dependency requires a newer WordPress version than production.</li><li>The update otherwise introduces an identified compatibility issue.</li></ul><h3 id="reviewing-dependabot-updates" tabindex="-1">Reviewing Dependabot updates <a class="header-anchor" href="#reviewing-dependabot-updates" aria-label="Permalink to “Reviewing Dependabot updates”">​</a></h3><p>For each Dependabot pull request:</p><ol><li>Review the dependency change and applicable release notes.</li><li>Confirm compatibility with the current WordPress version where applicable.</li><li>Review CI results.</li><li>Merge compatible updates.</li><li>Defer updates that cannot yet be safely merged.</li></ol><p>Prioritize critical and high-severity security updates.</p><p>Security alerts are available in the repository&#39;s <a href="https://github.com/bcgov/bcew-monorepo/security/dependabot" target="_blank" rel="noreferrer">Dependabot security alerts</a>.</p><h3 id="deferring-an-update" tabindex="-1">Deferring an update <a class="header-anchor" href="#deferring-an-update" aria-label="Permalink to “Deferring an update”">​</a></h3><p>When a dependency update cannot be merged:</p><ol><li>Close the Dependabot pull request.</li><li>Create an issue documenting: <ul><li>the dependency and version</li><li>why the update is blocked</li><li>what must change before it can be updated</li></ul></li><li>Add an <code>ignore</code> entry to <code>.github/dependabot.yml</code> and reference the issue.</li><li>Remove the <code>ignore</code> entry and close the issue when the dependency can be updated.</li></ol><p>Example:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">ignore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">dependency-name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@wordpress/block-editor&quot;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">    # Deferred: #123 — requires a newer production WordPress version.</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    versions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;14.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div>`,31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};